/**
 * Wall sweeps & reveals — types.
 *
 * A wall sweep is a horizontal profile extruded along the wall length
 * (cornice, baseboard, wainscot, cap). A reveal is a horizontal groove
 * cut into the wall face (architectural shadow line).
 *
 * Profiles are defined as 2D cross-sections in the wall's local
 * (u, h) space where:
 *   u = lateral offset from wall centreline (positive = exterior face)
 *   h = height above wall base
 *
 * The sweep geometry is generated by extruding the profile along the
 * wall's length direction, at the specified height.
 */

/** Sweep/reveal profile: a 2D polygon in (u, h) space. */
export interface SweepProfile {
  /** Profile id (e.g. "cornice-1", "baseboard-standard"). */
  id: string;
  /** Display name. */
  name: string;
  /** Profile type: sweep (adds material) or reveal (cuts material). */
  type: "sweep" | "reveal";
  /** 2D polygon vertices [u, h] — u in metres from wall centreline, h in metres from wall base. */
  vertices: Array<[number, number]>;
  /** Material color. */
  color: string;
}

/** A wall sweep/reveal placement on a host wall. */
export interface WallSweepPlacement {
  /** Host wall element ID. */
  wallId: string;
  /** Profile to apply. */
  profileId: string;
  /** Height on the wall (metres above wall base). */
  height: number;
  /** Which face(s): "exterior", "interior", or "both". */
  face: "exterior" | "interior" | "both";
  /** Optional: start offset along the wall (0 = wall start). */
  startOffset?: number;
  /** Optional: end offset along the wall (length of sweep, defaults to full wall). */
  endOffset?: number;
}

