/** Get a profile by ID. */
export function getProfile(id: string): SweepProfile | null {
  return BUILTIN_PROFILES.find((p) => p.id === id) ?? null;
}

/** List all profile IDs. */
export function listProfiles(): string[] {
  return BUILTIN_PROFILES.map((p) => p.id);
}

/** List profile display names (for UI dropdown). */
export function listProfileOptions(): Array<{ id: string; label: string }> {
  return BUILTIN_PROFILES.map((p) => ({ id: p.id, label: p.name }));
}
